    def first_present(d, keys, default=None):
        for k in keys:
            if isinstance(d, dict) and k in d:
                v = d.get(k)
                if v is not None:
                    return v
        return default

    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def get_pos(obj):
        if isinstance(obj, dict):
            for k in ("pos", "position", "loc", "location", "xy", "coord", "coords", "cell"):
                v = obj.get(k)
                p = get_pos(v)
                if p is not None:
                    return p
            x = obj.get("x")
            y = obj.get("y")
            if is_num(x) and is_num(y):
                return (int(x), int(y))
        elif isinstance(obj, (list, tuple)):
            if len(obj) == 2 and is_num(obj[0]) and is_num(obj[1]):
                return (int(obj[0]), int(obj[1]))
            if len(obj) == 1:
                return get_pos(obj[0])
        return None

    def norm_positions(v):
        out = []
        if v is None:
            return out
        if isinstance(v, dict):
            p = get_pos(v)
            if p is not None:
                out.append(p)
            else:
                for vv in v.values():
                    out.extend(norm_positions(vv))
        elif isinstance(v, (list, tuple)):
            p = get_pos(v)
            if p is not None:
                out.append(p)
            else:
                for vv in v:
                    out.extend(norm_positions(vv))
        return out

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_step(v):
        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    me = get_pos(first_present(observation, ("self", "agent", "player", "me", "agent_state", "self_state"), observation))
    if me is None:
        me = get_pos(first_present(observation, ("pos", "position", "loc", "location")))
    if me is None:
        return [0, 0]

    mode = first_present(observation, ("mode", "game_type", "task", "scenario", "objective"), "")
    mode = str(mode).lower()

    # Collect candidate sets
    resources = []
    for k in ("resources", "resource_positions", "collectibles", "items", "food", "targets"):
        resources.extend(norm_positions(observation.get(k) if isinstance(observation, dict) else None))

    enemies = []
    for k in ("enemies", "opponents", "enemy_positions", "others", "agents"):
        enemies.extend(norm_positions(observation.get(k) if isinstance(observation, dict) else None))

    territory = []
    for k in ("territory", "unclaimed", "frontier", "cells", "claimable"):
        territory.extend(norm_positions(observation.get(k) if isinstance(observation, dict) else None))

    blocked = set()
    for k in ("walls", "obstacles", "blocked", "blocked_cells", "impassable"):
        for p in norm_positions(observation.get(k) if isinstance(observation, dict) else None):
            blocked.add(p)

    # Grid bounds if available
    width = None
    height = None
    grid = first_present(observation, ("grid", "board", "map", "world"))
    if isinstance(grid, list) and grid:
        height = len(grid)
        if isinstance(grid[0], list):
